<?php
require __DIR__.'/config/config.php';
$search = trim($_GET['q'] ?? '');
$categoryId = (int) ($_GET['category_id'] ?? 0);
$categories = db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();
$sql = 'SELECT b.*, c.name category_name FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE b.is_active=1';
$params = [];
if ($search !== '') { $sql .= ' AND (b.title LIKE ? OR b.author LIKE ?)'; $params[] = "%$search%"; $params[] = "%$search%"; }
if ($categoryId > 0) { $sql .= ' AND b.category_id=?'; $params[] = $categoryId; }
$sql .= ' ORDER BY b.id DESC';
$query = db()->prepare($sql); $query->execute($params); $books = $query->fetchAll();
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cửa hàng - Nhà Sách Trí Tuệ</title><link rel="stylesheet" href="<?= BASE_URL ?>/style.css"></head><body><header class="topbar"><strong>NHÀ SÁCH TRÍ TUỆ</strong><span><a href="<?= BASE_URL ?>/shop.php">Trang chủ</a> · <?php if (!empty($_SESSION['customer'])): ?><a href="<?= BASE_URL ?>/account.php">Tài khoản</a> · <a href="<?= BASE_URL ?>/cart.php">Giỏ hàng</a> · <a href="<?= BASE_URL ?>/customer-logout.php">Đăng xuất</a><?php else: ?><a href="<?= BASE_URL ?>/customer-login.php">Đăng nhập</a> · <a href="<?= BASE_URL ?>/customer-register.php">Đăng ký</a><?php endif; ?></span></header><main class="container"><h1>Sách nổi bật</h1><form class="search-bar" method="get"><input name="q" value="<?= e($search) ?>" placeholder="Tìm theo tên sách hoặc tác giả"><select name="category_id"><option value="0">Tất cả danh mục</option><?php foreach ($categories as $category): ?><option value="<?= $category['id'] ?>" <?= $categoryId === (int) $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select><button>Tìm kiếm</button></form><div class="book-grid"><?php foreach ($books as $book): ?><article class="book-card"><a href="<?= BASE_URL ?>/book.php?id=<?= $book['id'] ?>"><div class="book-cover">📖</div><h2><?= e($book['title']) ?></h2></a><p><?= e($book['author']) ?> · <?= e($book['category_name']) ?></p><b><?= number_format((float) $book['price'],0,',','.') ?>đ</b><span class="muted"> · Còn <?= (int) $book['stock_quantity'] ?></span><form method="post" action="<?= BASE_URL ?>/cart.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="book_id" value="<?= $book['id'] ?>"><input type="hidden" name="action" value="add"><button <?= $book['stock_quantity'] < 1 ? 'disabled' : '' ?>>Thêm vào giỏ</button></form></article><?php endforeach; ?></div><?php if (!$books): ?><p>Không tìm thấy sách phù hợp.</p><?php endif; ?></main></body></html>
